import openpyxl, glob, docx

for f in sorted(glob.glob('/filesystem/**/*.xlsx', recursive=True)):
    wb = openpyxl.load_workbook(f, data_only=True)
    print('=== EXCEL:', f, wb.sheetnames)
    for name in wb.sheetnames:
        ws = wb[name]
        print(f'--- Sheet: {name} (rows: {ws.max_row}) ---')
        for r in list(ws.iter_rows(values_only=True))[:25]:
            if any(r):
                print(r)
        for r in list(ws.iter_rows(values_only=True))[25:]:
            if any(r) and any(k in str(r).lower() for k in ['cravenwood', 'darnwick', 'holcott', 'lockmere', 'marden', 'tresbay', 'municipal', 'waiver', 'witness', '779', '793', '061', 'arvexa', 'selvix', 'solmery', 'torvane', 'vexlar']):
                print('MATCH:', r)
"

