arguments.command:
python3 -c "
import docx, glob, pypdf

for f in sorted(glob.glob('/filesystem/Correspondence/*') + glob.glob('/filesystem/Standards/*')):
    if f.endswith('.docx'):
        doc = docx.Document(f)
        print('=== DOCX:', f)
        for p in doc.paragraphs:
            if p.text.strip(): print(p.text)
        for t in doc.tables:
            for r in t.rows:
                print([c.text.strip() for c in r.cells])
    elif f.endswith('.pdf'):
        reader = pypdf.PdfReader(f)
        print('=== PDF:', f, 'pages:', len(reader.pages))
        for i, page in enumerate(reader.pages):
            print(f'--- Page {i+1} ---')
            print(page.extract_text())
"

