python3 -c "
import glob, subprocess

terms = ['cravenwood', 'darnwick', 'holcott', 'lockmere', 'marden', 'tresbay', 'arvexa', 'selvix', 'eng-prc-014']
for p in sorted(glob.glob('/filesystem/**/*', recursive=True)):
    if p.endswith(('.pdf', '.docx', '.xlsx', '.eml', '.txt')):
        try:
            with open(p, 'rb') as f:
                data = f.read().lower()
            for t in terms:
                if t.encode() in data:
                    print(f'Match {t} in {p}')
        except Exception as e:
            pass
"

python3 -c "
import glob, subprocess, docx, openpyxl

terms = ['cravenwood', 'darnwick', 'holcott', 'lockmere', 'marden', 'tresbay', 'arvexa', 'selvix', 'eng-prc-014', '0779', '0793', '0061']
for p in sorted(glob.glob('/filesystem/**/*', recursive=True)):
    txt = ''
    if p.endswith('.pdf'):
        txt = subprocess.run(['pdftotext', p, '-'], capture_output=True, text=True).stdout
    elif p.endswith('.docx'):
        d = docx.Document(p)
        txt = '\n'.join([para.text for para in d.paragraphs] + [c.text for t in d.tables for r in t.rows for c in r.cells])
    elif p.endswith('.xlsx'):
        wb = openpyxl.load_workbook(p, data_only=True)
        txt = '\n'.join(str(c) for s in wb.sheetnames for r in wb[s].iter_rows(values_only=True) for c in r if c is not None)
    elif p.endswith('.eml'):
        with open(p) as f: txt = f.read()
    if txt:
        low = txt.lower()
        matched = [t for t in terms if t in low]
        if matched:
            print(f'{p}: {matched}')
"

