python3 -c "
import openpyxl, glob

for path in sorted(glob.glob('/filesystem/**/*.xlsx', recursive=True)):
    wb = openpyxl.load_workbook(path, data_only=True)
    for sheet in wb.sheetnames:
        ws = wb[sheet]
        for r_idx, row in enumerate(ws.iter_rows(values_only=True), 1):
            row_str = ' '.join(str(v) for v in row if v is not None)
            for kw in ['Cravenwood', 'Darnwick', 'Holcott', 'Lockmere', 'Marden', 'Tresbay', 'PXA-2024-0779', 'PXA-2024-0793', 'PXA-2025-0061', 'Solberg', 'Rennick', 'Halbrook', 'Ondras', 'Selvix', 'Arvexa', 'Solmery', 'Torvane', 'Vexlar']:
                if kw.lower() in row_str.lower():
                    print(f'{path} [{sheet}] Row {r_idx}: {row}')
                    break
"

